using System;
using System.Collections.Generic;
using System.Linq;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Media;
using MapleMeter;
namespace MapleMeter {
 public static class HistoryForm {
  public static List<HistoryRecord> Filter(IEnumerable<HistoryRecord> source,int range,string query,int sort,DateTime today){var rows=source.Where(r=>r.Seconds>Storage.MinimumSeconds);if(range==1)rows=rows.Where(r=>r.Started.Date==today.Date);if(range==2)rows=rows.Where(r=>r.Started>=today.Date.AddDays(-6)&&r.Started<today.Date.AddDays(1));if(!string.IsNullOrWhiteSpace(query))rows=rows.Where(r=>(r.Map??"").IndexOf(query.Trim(),StringComparison.OrdinalIgnoreCase)>=0);return(sort==1?rows.OrderByDescending(r=>r.Rate):sort==2?rows.OrderByDescending(r=>r.Seconds):rows.OrderByDescending(r=>r.Started)).ToList();}
  public static double WeightedRate(IEnumerable<HistoryRecord> rows){double time=rows.Sum(r=>r.Seconds);return time==0?0:rows.Sum(r=>(double)r.Gain)*3600/time;}
 }
}
namespace MapleWarm {
 public sealed class History:Surface {
  readonly Engine engine;readonly bool demoMode;List<HistoryRecord> all,shown;int range=0,sort=0,skipped;TextBox search;TextBlock count,total,experience,average,detail;StackPanel table;MinuteGraph graph;string selectedId;Button export;bool rebuilding;string query="";
  public History(bool demo=false,Engine engine=null):base("MapleMeter 暖光版 · 练级历史",640,610){this.engine=engine;demoMode=demo;all=demo?DemoRecords():Storage.Load(Storage.Folder,out skipped);Build();App.FontChanged+=Build;Closed+=delegate{App.FontChanged-=Build;};}
  public void Reload(){if(!demoMode){all=Storage.Load(Storage.Folder,out skipped);Refresh();}}
  static List<HistoryRecord> DemoRecords(){var list=new List<HistoryRecord>();for(int i=0;i<3;i++){var r=new HistoryRecord{Id="demo-"+i,Started=DateTime.Now.AddHours(-i*2),Map=i==1?"Victoria Road / Ellinia":"Victoria Road / Henesys",Seconds=1200+i*60,Gain=42160+i*2000,StartLevel=27,EndLevel=27};for(int j=0;j<20;j++)r.Minutes.Add(new MinuteData{Index=j,Seconds=60,Gain=j==5?-480:600+j%6*500});list.Add(r);}return list;}
  TextBlock Cell(string text,double size,double x,double y,double w,double h,Brush color=null,bool bold=false,TextAlignment align=TextAlignment.Left){var t=App.Text(text,size,color,bold);t.TextAlignment=align;return App.At(canvas,t,x,y,w,h);}
  void Build(){rebuilding=true;Reset();Header("练级历史");App.At(canvas,App.Button("每日统计",null,()=>new DailyWindow(engine,demoMode){Owner=this}.Show()),390,7,140,30);App.At(canvas,App.Card(),20,52,600,76);string[] labels={"有效记录","有效时长","净经验","平均 / 小时"};var stats=new TextBlock[4];for(int i=0;i<4;i++){Cell(labels[i],11,28+i*150,59,134,22,App.Muted,false,TextAlignment.Center);stats[i]=Cell("—",19,28+i*150,84,134,30,i==2?App.Green:App.Ink,true,TextAlignment.Center);}count=stats[0];total=stats[1];experience=stats[2];average=stats[3];
   App.At(canvas,MenuButton(new[]{"全部时间","今天","最近 7 天"},range,i=>{range=i;Refresh();}),20,142,138,34);App.At(canvas,MenuButton(new[]{"最近记录优先","效率从高到低","时长从长到短"},sort,i=>{sort=i;Refresh();}),170,142,148,34);
   search=new TextBox{Text=query,FontFamily=App.Chinese,FontSize=13,FontWeight=App.BodyWeight,Padding=new Thickness(10,0,10,0),VerticalContentAlignment=VerticalAlignment.Center,Background=Brushes.Transparent,Foreground=App.Ink,BorderThickness=new Thickness(0)};var sg=new Grid();sg.Children.Add(search);var placeholder=App.Text("搜索地图",13,App.Muted);placeholder.Margin=new Thickness(10,0,0,0);placeholder.IsHitTestVisible=false;placeholder.Visibility=query.Length==0?Visibility.Visible:Visibility.Collapsed;sg.Children.Add(placeholder);search.TextChanged+=delegate{query=search.Text;placeholder.Visibility=query.Length==0?Visibility.Visible:Visibility.Collapsed;if(!rebuilding)Refresh();};App.At(canvas,App.Card(sg,App.Brush("#FFFCF8"),10,true),330,142,290,34);
   var headers=Row(new[]{"开始时间","地图","有效时长","净经验","EXP / 小时","状态"},true);App.At(canvas,headers,20,188,600,32);table=new StackPanel();var scroller=new ScrollViewer{Content=table,VerticalScrollBarVisibility=ScrollBarVisibility.Auto,HorizontalScrollBarVisibility=ScrollBarVisibility.Disabled};App.At(canvas,App.Card(scroller,App.Brush("#FFFBF5"),10,true),20,220,600,168);
   detail=Cell("",11,32,398,576,26,App.Muted);App.At(canvas,App.Card(null,null,12,true),20,430,600,116);graph=new MinuteGraph();App.At(canvas,graph,32,439,576,100);Cell(skipped>0?skipped+" 条损坏记录已跳过":"",11,20,563,360,26,App.Muted);export=App.Button("导出筛选结果",null,Export);App.At(canvas,export,462,560,158,34);rebuilding=false;Refresh();}
  Button MenuButton(string[] labels,int index,Action<int> apply){Button b=null;b=App.Button(labels[index]+" ▾",null,()=>{var menu=new ContextMenu{FontFamily=App.Chinese,FontSize=13,FontWeight=App.BodyWeight,Background=App.Brush("#FFF9EF"),Foreground=App.Ink};for(int i=0;i<labels.Length;i++){int selected=i;var item=new MenuItem{Header=labels[i],Foreground=App.Ink};var outline=new FrameworkElementFactory(typeof(Border));outline.Name="Highlight";outline.SetValue(Border.PaddingProperty,new Thickness(14,8,14,8));outline.SetValue(Border.BackgroundProperty,App.Brush("#FFF9EF"));var caption=new FrameworkElementFactory(typeof(ContentPresenter));caption.SetValue(ContentPresenter.ContentSourceProperty,"Header");outline.AppendChild(caption);var template=new ControlTemplate(typeof(MenuItem)){VisualTree=outline};var hover=new Trigger{Property=MenuItem.IsHighlightedProperty,Value=true};hover.Setters.Add(new Setter(Border.BackgroundProperty,App.Brush("#FFE0BF"),"Highlight"));template.Triggers.Add(hover);item.Template=template;item.Click+=delegate{b.Content=App.Text(labels[selected]+" ▾",13);apply(selected);};menu.Items.Add(item);}menu.PlacementTarget=b;menu.IsOpen=true;});return b;}
  Grid Row(string[] cells,bool header=false){var row=new Grid{Height=header?32:40,Background=App.Brush(header?"#F8EEE1":"#FFFBF5")};double[] widths={88,131,82,94,104,81};for(int i=0;i<6;i++){row.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(widths[i])});var text=App.Text(cells[i],header?11:12,!header&&i==3?App.Green:App.Ink,false,!header&&i!=1&&i!=5);text.TextAlignment=i>=2&&i<=4?TextAlignment.Right:i==5?TextAlignment.Center:TextAlignment.Left;var box=new Border{Child=text,Padding=new Thickness(9,0,9,0),BorderBrush=App.Line,BorderThickness=new Thickness(0,0,0,1)};Grid.SetColumn(box,i);row.Children.Add(box);}return row;}
  static string ShortMap(string name){return string.Join(" → ",(name??"").Split(new[]{" → "},StringSplitOptions.None).Select(x=>x.Contains(" / ")?x.Substring(x.LastIndexOf(" / ",StringComparison.Ordinal)+3):x));}
  void Refresh(){shown=HistoryForm.Filter(all,range,query,sort,DateTime.Now);count.Text=shown.Count+" 次";total.Text=App.Duration(shown.Sum(x=>x.Seconds));experience.Text=App.Number(shown.Sum(x=>(double)x.Gain));average.Text=App.Number(HistoryForm.WeightedRate(shown));table.Children.Clear();export.IsEnabled=shown.Count>0;foreach(var record in shown){var r=record;var row=Row(new[]{r.Started.ToString("MM-dd HH:mm"),ShortMap(r.Map),App.Duration(r.Seconds),(r.Estimated?"≈ ":"")+App.Number(r.Gain),App.Number(r.Rate),r.Quality});row.Tag=r;row.ToolTip=r.Map+"\n经验减少 "+App.Number(r.Loss);row.Cursor=System.Windows.Input.Cursors.Hand;row.MouseLeftButtonDown+=delegate{Select(r);};table.Children.Add(row);}if(shown.Count==0){var empty=App.Text(all.Count==0?"暂无有效记录":"没有匹配的记录",13,App.Muted);empty.TextAlignment=TextAlignment.Center;empty.Margin=new Thickness(0,40,0,0);table.Children.Add(empty);}Select(shown.FirstOrDefault(x=>x.Id==selectedId)??shown.FirstOrDefault());}
  void Select(HistoryRecord r){selectedId=r==null?null:r.Id;foreach(var row in table.Children.OfType<Grid>())row.Background=App.Brush(((HistoryRecord)row.Tag).Id==selectedId?"#FFE0BF":"#FFFBF5");detail.Text=r==null?"":r.Started.ToString("yyyy-MM-dd HH:mm")+" · Lv. "+r.StartLevel+" → "+r.EndLevel+" · "+r.Quality+(r.Legacy?" · 旧版无分钟明细":"");graph.SetData(r==null?null:r.Minutes,false);}
  void Export(){var dialog=new Microsoft.Win32.SaveFileDialog{Filter="CSV 文件|*.csv",FileName="MapleMeter-暖光版-练级记录.csv"};if(dialog.ShowDialog(this)==true)try{Storage.Export(dialog.FileName,shown);}catch(Exception ex){MessageBox.Show(this,"导出失败："+ex.Message);}}
 }
}
